// HandTexBlob.swift - realistic skin texture for the hand mesh, transferred
// offline from the CC0 "fps arms (rigged only)" asset by para
// (https://opengameart.org/content/fps-arms-rigged-only; mesh+texture made with
// MakeHuman's bundled CC0 assets, re-baked by the author; MakeHuman bundled
// textures are CC0 1.0 per github.com/makehumancommunity/makehuman LICENSE.md).
// Transfer: per-finger Procrustes alignment of the two rigs (both share
// 3-joints-per-finger + wrist), nearest-surface color sampling onto the
// existing 8120-vertex Innerscene hand mesh (CC0), rasterized into its own
// (previously unused) UV island renormalized to 1024px. No geometry change.
// See ASSETS.md.
// Payloads are single-line string literals: multiline """ blocks inject
// newlines that break Data(base64Encoded:), and long "+" literal chains blow
// up the build. UVs are Float32 pairs, V flipped for SceneKit's bottom-left
// texture origin. Texture is 1024px JPEG q95 4:4:4.
import Foundation
import UIKit

enum HandTexBlob {
    static let image: UIImage = {
        guard let data = Data(base64Encoded: texB64, options: [.ignoreUnknownCharacters]),
              let img = UIImage(data: data) else {
            // Loud failure: a magenta hand cannot be mistaken for skin.
            NSLog("[HANDTEX] texture decode FAILED - using magenta fallback")
            let renderer = UIGraphicsImageRenderer(size: CGSize(width: 4, height: 4))
            return renderer.image { ctx in
                UIColor.magenta.setFill()
                ctx.fill(CGRect(x: 0, y: 0, width: 4, height: 4))
            }
        }
        return img
    }()

    static let uvData: Data = Data(base64Encoded: uvB64)!

